/** M2-R01: owning-module queries only, in the genuine Identity command transaction. */
public final class JdbcMerchantGovernanceViews implements MerchantGovernanceViews {
    private static final JsonMapper JSON=JsonMapper.builder().build();
    private static final UUID ROOT=UUID.fromString("507a48f6-0ddc-4a82-a1a5-5862d3387300");
    private final DataSource source;private final JdbcTemplate jdbc;private final JdbcMerchantApplicationReviews governance;private final AdminCommandAdmission admission;
    private final MerchantFingerprints fingerprints;private final ProtectedGovernancePayloads protection;private final Clock clock;private final MerchantViewCursor cursors;
    public JdbcMerchantGovernanceViews(DataSource source,JdbcMerchantApplicationReviews governance,AdminCommandAdmission admission,MerchantFingerprints fingerprints,ProtectedGovernancePayloads protection,Clock clock){this.source=source;this.jdbc=new JdbcTemplate(source);this.governance=governance;this.admission=admission;this.fingerprints=fingerprints;this.protection=protection;this.clock=clock;cursors=new MerchantViewCursor(fingerprints,clock);}
    private static GovernanceFailure fail(GovernanceFailure.Code code){return new GovernanceFailure(code);}
    private static UUID id(UUID id){if(id==null||id.equals(new UUID(0,0)))throw fail(VALIDATION_FAILED);return id;}
    private static Target app(UUID id){return new Target(Kind.APPLICATION,id(id));}
    private static Target org(UUID id){return new Target(Kind.ORGANIZATION,id(id));}
    private void admit(AdminCommandContext actor){admission.requireCurrent(actor);if(!org.springframework.transaction.support.TransactionSynchronizationManager.hasResource(source)||!Set.of("LOCAL","TEST").contains(actor.environment()))throw fail(ACCESS_DENIED);}
    private <T>T scoped(AdminCommandContext actor,Target target,List<String> permissions,Function<GovernanceScope,T> work){admit(actor);return governance.withScope(actor,target,s->{permissions.forEach(p->s.require(p,target));T value=work.apply(s);permissions.forEach(p->s.require(p,target));return value;});}
    private static String json(Object value){return JSON.writeValueAsString(value);}
    private static String normalize(String value,int maximum){if(value==null)return null;if(value.isBlank()||value.codePointCount(0,value.length())>maximum||value.codePoints().anyMatch(c->Character.isISOControl(c)||c==0x2028||c==0x2029||c>=0xd800&&c<=0xdfff))throw fail(VALIDATION_FAILED);return Normalizer.normalize(value,Normalizer.Form.NFC);}
    private static String legal(String value){String normalized=normalize(value,80);return normalized==null?null:normalized.replaceAll("[- ./_]","");}
    private static String name(String value){String normalized=normalize(value,240);return normalized==null?null:normalized.strip().toLowerCase(Locale.ROOT);}
    private static int size(PageQuery page){int size=page==null||page.size()==null?20:page.size();if(size<1||size>50||page!=null&&page.cursor()!=null&&page.cursor().length()>512)throw fail(VALIDATION_FAILED);return size;}
    private String hash(String operation,String... values){return HexFormat.of().formatHex(fingerprints.hash(fingerprints.activeKey(),operation,ROOT,1,values));}
    private record Slice<T>(List<T> items,String next){}
    private <T>Slice<T> page(AdminCommandContext actor,List<T> values,PageQuery page,String query,String source){int size=size(page),offset=cursors.offset(page==null?null:page.cursor(),actor.accountId(),actor.realmId(),actor.permissionVersion(),query,source,size);if(offset>values.size())throw fail(SNAPSHOT_EXPIRED);int end=Math.min(values.size(),offset+size);return new Slice<>(List.copyOf(values.subList(offset,end)),end<values.size()?cursors.advance(page==null?null:page.cursor(),actor.accountId(),actor.realmId(),actor.permissionVersion(),query,source,end,size):null);}
    private Map<String,Object> application(UUID id){return jdbc.queryForList("SELECT a.*,r.submitted_input,r.content_digest,r.policy_version,r.application_version,r.activation_display_name FROM merchant.application a JOIN merchant.application_revision r ON r.application_id=a.id AND r.revision=a.submitted_revision WHERE a.id=?",id).stream().findFirst().orElseThrow(()->fail(RESOURCE_NOT_FOUND));}
    private JsonNode input(Map<String,Object> row){return JSON.readTree(row.get("submitted_input").toString());}
    private UUID disclosure(AdminCommandContext actor,Target target,Map<String,Object> row,Object purpose){
        UUID event=UUID.randomUUID();long revision=target.kind()==Kind.APPLICATION?((Number)row.get("submitted_revision")).longValue():0;
        byte[] encrypted=protection.seal(event,target.id(),revision,"READ_DISCLOSURE",json(purpose));
        try{jdbc.update("INSERT INTO merchant.governance_event(id,actor_kind,actor_id,realm_id,target_type,target_id,application_id,organization_id,policy_id,operation,revision,prior_version,new_version,reason_code,protected_payload,request_id,occurred_at) VALUES (?,'SYSTEM',?,?,?,?,?,?,?,'READ_DISCLOSURE',?,?,?,'MERCHANT_REVIEW',?,?,?)",event,actor.accountId(),actor.realmId(),target.kind()==Kind.APPLICATION?"APPLICATION":"ORGANIZATION",target.id(),target.kind()==Kind.APPLICATION?target.id():null,target.kind()==Kind.ORGANIZATION?target.id():null,row.get("policy_id"),revision==0?null:revision,row.get("version"),row.get("version"),encrypted,actor.requestId(),Timestamp.from(clock.instant()));return event;}finally{Arrays.fill(encrypted,(byte)0);}
    }
    private List<UUID> applicationIds(AdminCommandContext actor){
        var policies=jdbc.query("SELECT s.policy_id FROM merchant.business_reviewer_scope s JOIN merchant.application_policy p ON p.id=s.policy_id WHERE s.account_id=? AND s.realm_id=? AND s.scope_type='POLICY' AND s.state='ACTIVE' AND s.expires_at>? AND s.permissions @> ARRAY['application.read','application.evidence.read']::text[] AND p.state='PUBLISHED' AND p.environment=? AND p.valid_from<=? AND (p.valid_to IS NULL OR p.valid_to>?) ORDER BY s.policy_id",(r,n)->r.getObject(1,UUID.class),actor.accountId(),actor.realmId(),Timestamp.from(clock.instant()),actor.environment(),Timestamp.from(clock.instant()),Timestamp.from(clock.instant()));
        if(policies.isEmpty())throw fail(ACCESS_DENIED);
        var result=jdbc.query("SELECT id FROM merchant.application WHERE submitted_revision IS NOT NULL AND policy_id=ANY(?::uuid[]) ORDER BY first_submitted_at DESC,id DESC LIMIT 10001",(r,n)->r.getObject(1,UUID.class),(Object)policies.toArray(UUID[]::new));if(result.size()>10000)throw fail(SERVICE_UNAVAILABLE);return result;
    }
    @Override public ApplicationSearchPage searchApplications(AdminCommandContext actor,ApplicationSearch q){
        admit(actor);if(q==null||!"MERCHANT_REVIEW".equals(q.purpose())||q.from()==null||q.to()==null||q.from().isAfter(q.to())||q.to().isAfter(LocalDate.ofInstant(clock.instant(),ZoneId.of("Asia/Ho_Chi_Minh")))||java.time.temporal.ChronoUnit.DAYS.between(q.from(),q.to())>=366)throw fail(VALIDATION_FAILED);size(q.page());
        if(q.dueBefore()!=null||q.overdue()!=null)throw fail(POLICY_UNAVAILABLE);
        if(q.state()!=null&&!Set.of("SUBMITTED","UNDER_REVIEW","NEEDS_INFORMATION","APPROVED","REJECTED","WITHDRAWN").contains(q.state()))throw fail(VALIDATION_FAILED);
        if(q.checkCode()!=null&&!Set.of("BUSINESS_KEY_CONFLICT","CONTACT_REVERIFY_REQUIRED","EVIDENCE_NOT_CLEAN","REVIEWER_CONFLICT").contains(q.checkCode()))throw fail(VALIDATION_FAILED);
        String searchName=name(q.registeredName()),searchLegal=legal(q.legalIdentifier());var matches=new ArrayList<ApplicationSummary>();var capture=new ArrayList<String>();var matchedRows=new HashMap<UUID,Map<String,Object>>();
        for(UUID id:applicationIds(actor))scoped(actor,app(id),List.of("application.read","application.evidence.read"),scope->{var row=application(id);var submitted=input(row);var summary=governance.summaryForViews(actor,id,scope);
            capture.add(id+"|"+row.get("version")+"|"+HexFormat.of().formatHex((byte[])row.get("content_digest"))+"|"+scope.version());
            LocalDate date=((Timestamp)row.get("first_submitted_at")).toInstant().atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toLocalDate();
            if(!date.isBefore(q.from())&&!date.isAfter(q.to())&&(q.state()==null||q.state().equals(row.get("state")))&&(q.policyId()==null||q.policyId().equals(row.get("policy_id")))&&(q.reviewerId()==null||q.reviewerId().equals(summary.reviewerId()))&&(q.applicationId()==null||q.applicationId().equals(id))&&(q.applicantAccountId()==null||q.applicantAccountId().equals(row.get("applicant_account_id")))&&(searchName==null||searchName.equals(name(submitted.path("registeredName").asString())))&&(searchLegal==null||searchLegal.equals(legal(submitted.path("legalIdentifier").asString())))){
                String full=submitted.path("registeredName").asString(),identifier=submitted.path("legalIdentifier").asString();String masked=full.isEmpty()?"***":new String(Character.toChars(full.codePointAt(0)))+"***";int at=identifier.offsetByCodePoints(0,Math.max(0,identifier.codePointCount(0,identifier.length())-4));
                var facts=q.checkCode()==null?List.<Check>of():reviewChecks(actor,id,row);capture.add("checks|"+id+"|"+json(facts));
                if(q.checkCode()!=null&&facts.stream().noneMatch(f->f.code().equals(q.checkCode())&&f.result().equals("FAIL")))return null;
                matches.add(new ApplicationSummary(id,summary.state(),summary.revision(),summary.version(),masked,"***"+identifier.substring(at),summary.policyId(),summary.reviewerId(),summary.firstSubmittedAt(),summary.updatedAt(),summary.activation(),summary.allowedActions()));matchedRows.put(id,row);
            }return null;});
        String query=hash("merchantViewQuery",json(new ApplicationSearch(q.from(),q.to(),q.state(),q.policyId(),q.reviewerId(),q.applicationId(),q.applicantAccountId(),searchName,searchLegal,q.purpose(),null,null,null,q.checkCode()))),source=hash("merchantViewSource",json(capture));var page=page(actor,matches,q.page(),query,source);
        for(var row:page.items())scoped(actor,app(row.id()),List.of("application.read","application.evidence.read"),s->{disclosure(actor,app(row.id()),matchedRows.get(row.id()),Map.of("purpose","MERCHANT_REVIEW","kind","SEARCH","queryDigest",query));return null;});admission.requireCurrent(actor);return new ApplicationSearchPage(page.items(),page.next(),source,matches.size());
    }
    private Map<String,Object> organization(UUID id){return jdbc.queryForList("SELECT o.*,x.application_id,x.policy_id,x.revision AS activation_revision FROM merchant.organization o LEFT JOIN merchant.application_activation x ON x.organization_id=o.id WHERE o.id=?",id).stream().findFirst().orElseThrow(()->fail(RESOURCE_NOT_FOUND));}
    private OrganizationRow organizationRow(Map<String,Object> row){
        UUID id=(UUID)row.get("id"),owner=(UUID)row.get("initial_owner_membership_id");var counts=new TreeMap<String,Map<String,Long>>();jdbc.query("SELECT role,state,count(*) AS n FROM merchant.membership WHERE organization_id=? GROUP BY role,state ORDER BY role,state",r->{counts.computeIfAbsent(r.getString("role"),k->new TreeMap<>()).put(r.getString("state"),r.getLong("n"));},id);
        var activation=jdbc.query("SELECT * FROM merchant.application_activation WHERE organization_id=?",(r,n)->new ActivationOutcome(r.getObject("application_id",UUID.class),r.getLong("revision"),r.getObject("decision_event_id",UUID.class),id,owner,"ACTIVE",r.getTimestamp("activated_at").toInstant()),id).stream().findFirst().orElse(null);
        return new OrganizationRow(id,(String)row.get("display_name"),(String)row.get("state"),(String)row.get("admission_origin"),((Number)row.get("version")).longValue(),owner,owner,null,activation,counts);
    }
    @Override public OrganizationSearchPage searchOrganizations(AdminCommandContext actor,OrganizationSearch q){
        admit(actor);if(q==null||!"ORGANIZATION_OVERSIGHT".equals(q.purpose()))throw fail(VALIDATION_FAILED);size(q.page());if(q.state()!=null&&!Set.of("ACTIVE","SUSPENDED").contains(q.state()))throw fail(POLICY_UNAVAILABLE);
        if(q.admissionOrigin()!=null&&!Set.of("APPLICATION_APPROVED","LOCAL_OPERATOR_PROVISIONED").contains(q.admissionOrigin())||q.activatedFrom()!=null&&q.activatedTo()!=null&&q.activatedFrom().isAfter(q.activatedTo()))throw fail(VALIDATION_FAILED);
        String searchName=name(q.registeredName()),searchLegal=legal(q.legalIdentifier());var ids=jdbc.query("SELECT s.organization_id FROM merchant.business_reviewer_scope s JOIN merchant.organization o ON o.id=s.organization_id WHERE s.account_id=? AND s.realm_id=? AND s.scope_type='ORGANIZATION' AND s.state='ACTIVE' AND s.expires_at>? AND s.permissions @> ARRAY['org.read','org.profile.read']::text[] AND o.environment=? ORDER BY s.organization_id",(r,n)->r.getObject(1,UUID.class),actor.accountId(),actor.realmId(),Timestamp.from(clock.instant()),actor.environment());if(ids.isEmpty())throw fail(ACCESS_DENIED);
        var matches=new ArrayList<OrganizationRow>();var capture=new ArrayList<String>();var rows=new HashMap<UUID,Map<String,Object>>();
        for(UUID id:ids)scoped(actor,org(id),List.of("org.read","org.profile.read"),scope->{var row=organization(id);var value=organizationRow(row);capture.add(json(value)+scope.version());if(q.organizationId()!=null&&!q.organizationId().equals(id)||q.state()!=null&&!q.state().equals(value.state())||q.policyId()!=null&&!q.policyId().equals(row.get("policy_id"))||q.admissionOrigin()!=null&&!q.admissionOrigin().equals(value.admissionOrigin()))return null;
            if(q.currentOwnerAccountId()!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM merchant.membership WHERE id=? AND organization_id=? AND account_id=?)",Boolean.class,value.currentOwnerMembershipId(),id,q.currentOwnerAccountId())))return null;
            if(row.get("application_id")==null){if(searchName!=null||searchLegal!=null||q.activatedFrom()!=null||q.activatedTo()!=null)throw fail(POLICY_UNAVAILABLE);}else{var r=revision((UUID)row.get("application_id"),((Number)row.get("activation_revision")).longValue());JsonNode fields=JSON.readTree(r.get("submitted_input").toString());LocalDate activated=value.activation().activatedAt().atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toLocalDate();if(searchName!=null&&!searchName.equals(name(fields.path("registeredName").asString()))||searchLegal!=null&&!searchLegal.equals(legal(fields.path("legalIdentifier").asString()))||q.activatedFrom()!=null&&activated.isBefore(q.activatedFrom())||q.activatedTo()!=null&&activated.isAfter(q.activatedTo()))return null;}
            matches.add(value);rows.put(id,row);return null;});
        String query=hash("merchantViewQuery",json(new OrganizationSearch(q.state(),q.policyId(),q.organizationId(),searchName,searchLegal,q.currentOwnerAccountId(),q.activatedFrom(),q.activatedTo(),q.purpose(),null,q.admissionOrigin()))),source=hash("merchantViewSource",json(capture));var page=page(actor,matches,q.page(),query,source);for(var row:page.items())scoped(actor,org(row.id()),List.of("org.read","org.profile.read"),s->{disclosure(actor,org(row.id()),rows.get(row.id()),Map.of("purpose","ORGANIZATION_OVERSIGHT","kind","SEARCH","queryDigest",query));return null;});return new OrganizationSearchPage(page.items(),page.next(),source,matches.size());
    }
    private Map<String,Object> revision(UUID id,long revision){return jdbc.queryForList("SELECT * FROM merchant.application_revision WHERE application_id=? AND revision=?",id,revision).stream().findFirst().orElseThrow(()->fail(RESOURCE_NOT_FOUND));}
    private Instant verified(UUID id,long revision,Map<String,Object> row){String op=revision==1?"SUBMIT":"RESUBMIT";var event=jdbc.queryForMap("SELECT id,protected_payload FROM merchant.governance_event WHERE application_id=? AND revision=? AND operation=? AND new_version=?",id,revision,op,row.get("application_version"));var fact=JSON.readTree(protection.open((UUID)event.get("id"),id,revision,op,(byte[])event.get("protected_payload"))).get("contactFact");if(fact==null||!id.toString().equals(fact.path("applicationId").asString())||fact.path("revision").asLong()!=revision)throw fail(CONTACT_PROOF_REQUIRED);return Instant.parse(fact.path("verifiedAt").asString());}
    private List<UUID> evidence(UUID id,long revision){return jdbc.query("SELECT evidence_id FROM merchant.application_revision_evidence WHERE application_id=? AND revision=? ORDER BY evidence_id",(r,n)->r.getObject(1,UUID.class),id,revision);}
    @Override public RevisionComparison compare(AdminCommandContext actor,UUID id,ComparisonRequest q){return scoped(actor,app(id),List.of("application.read","application.evidence.read"),scope->{if(q==null||!"MERCHANT_REVIEW".equals(q.purpose())||q.fromRevision()<1||q.toRevision()<=q.fromRevision())throw fail(VALIDATION_FAILED);governance.verifyForViews(actor,id);var current=application(id);var before=revision(id,q.fromRevision());var after=revision(id,q.toRevision());var a=JSON.readTree(before.get("submitted_input").toString());var b=JSON.readTree(after.get("submitted_input").toString());var changes=new ArrayList<FieldChange>();
        for(String field:List.of("entityType","jurisdiction","registeredName","legalIdentifier","registeredAddress","operatingAddress","representativeName","representativeEmail","representativeRelationship","declarations"))if(!Objects.equals(a.get(field),b.get(field)))changes.add(new FieldChange(field,a.get(field),b.get(field)));
        if(!Objects.equals(before.get("activation_display_name"),after.get("activation_display_name")))changes.add(new FieldChange("activationDisplayName",before.get("activation_display_name"),after.get("activation_display_name")));
        var old=evidence(id,q.fromRevision());var newer=evidence(id,q.toRevision());UUID event=disclosure(actor,app(id),current,Map.of("purpose",q.purpose(),"kind","REVISION_COMPARISON","fromRevision",q.fromRevision(),"toRevision",q.toRevision()));return new RevisionComparison(id,q.fromRevision(),q.toRevision(),HexFormat.of().formatHex((byte[])before.get("content_digest")),HexFormat.of().formatHex((byte[])after.get("content_digest")),changes,newer.stream().filter(v->!old.contains(v)).toList(),old.stream().filter(v->!newer.contains(v)).toList(),new ContactTimes(verified(id,q.fromRevision(),before),verified(id,q.toRevision(),after)),event);});}
    private Map<String,Object> block(String availability,String source,Map<String,Object> fields){var value=new LinkedHashMap<String,Object>();value.put("availability",availability);value.put("sourceVersion",availability.equals("AVAILABLE")?source:null);value.put("asOf",availability.equals("AVAILABLE")?clock.instant():null);value.put("reason",availability.equals("AVAILABLE")?null:"SOURCE_NOT_IMPLEMENTED");value.putAll(fields);return value;}
    @Override public OrganizationProfile profile(AdminCommandContext actor,UUID id,DisclosureRequest q){return scoped(actor,org(id),List.of("org.read","org.profile.read"),scope->{if(q==null||!"ORGANIZATION_OVERSIGHT".equals(q.purpose())||q.page()!=null)throw fail(VALIDATION_FAILED);var row=organization(id);var legal=block("UNAVAILABLE",null,Map.of());var contact=block("UNAVAILABLE",null,Map.of());UUID application=(UUID)row.get("application_id");if(application!=null){var r=revision(application,((Number)row.get("activation_revision")).longValue());var input=JSON.readTree(r.get("submitted_input").toString());var fields=new LinkedHashMap<String,Object>();for(String key:List.of("registeredName","entityType","jurisdiction","legalIdentifier","registeredAddress","operatingAddress"))fields.put(key,input.get(key));legal=block("AVAILABLE",r.get("policy_version").toString(),fields);String email=input.path("representativeEmail").asString();int at=email.indexOf('@');contact=block("AVAILABLE",r.get("policy_version").toString(),Map.of("representativeName",input.path("representativeName").asString(),"relationship",input.path("representativeRelationship").asString(),"verifiedAt",verified(application,((Number)row.get("activation_revision")).longValue(),r),"maskedEmail",at<0?"***":"***"+email.substring(at)));}
        var facilities=jdbc.queryForList("SELECT id,code,name,state FROM merchant.facility WHERE organization_id=? ORDER BY id",id);UUID event=disclosure(actor,org(id),row,Map.of("purpose",q.purpose(),"kind","PROFILE"));UUID owner=(UUID)row.get("initial_owner_membership_id");return new OrganizationProfile(id,((Number)row.get("version")).longValue(),owner,owner,application,legal,contact,block("AVAILABLE",row.get("version").toString(),Map.of("items",facilities)),block("UNAVAILABLE",null,Map.of()),block("UNAVAILABLE",null,Map.of()),event);});}
    @Override public MembershipPage members(AdminCommandContext actor,UUID id,DisclosureRequest q){return scoped(actor,org(id),List.of("org.read","org.members.read"),scope->{if(q==null||!"ORGANIZATION_OVERSIGHT".equals(q.purpose()))throw fail(VALIDATION_FAILED);size(q.page());var row=organization(id);UUID owner=(UUID)row.get("initial_owner_membership_id");var members=jdbc.query("SELECT id,account_id,role,state,version,authority_version FROM merchant.membership WHERE organization_id=? ORDER BY id",(r,n)->new Member(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),r.getLong(5),r.getLong(6),owner.equals(r.getObject(1,UUID.class)),owner.equals(r.getObject(1,UUID.class))),id);long pending=jdbc.queryForObject("SELECT count(*) FROM merchant.team_invitation WHERE organization_id=? AND state='PENDING' AND expires_at>?",Long.class,id,Timestamp.from(clock.instant()));String source=hash("merchantViewSource",scope.version(),row.get("version").toString(),json(members),Long.toString(pending));var page=page(actor,members,q.page(),hash("merchantViewQuery","MEMBERS",id.toString()),source);UUID event=disclosure(actor,org(id),row,Map.of("purpose",q.purpose(),"kind","MEMBERS"));return new MembershipPage(id,((Number)row.get("version")).longValue(),page.items(),pending,page.next(),event);});}
    private Comment commentRow(Map<String,Object> row){UUID event=(UUID)row.get("event_id"),app=(UUID)row.get("application_id");long rev=((Number)row.get("revision")).longValue();var body=JSON.readTree(protection.open(event,app,rev,"READ_DISCLOSURE",(byte[])row.get("protected_text")));if(!"MERCHANT_REVIEW_COMMENT".equals(body.path("purpose").asString()))throw fail(ACCESS_DENIED);return new Comment((UUID)row.get("id"),app,rev,(UUID)row.get("actor_id"),((Timestamp)row.get("created_at")).toInstant(),body.path("text").asString());}
    @Override public Comment comment(AdminCommandContext actor,UUID id,CommentInput q,long version,UUID key){return scoped(actor,app(id),List.of("application.read","application.comment.write"),scope->{if(q==null||q.revision()<1||version<1)throw fail(VALIDATION_FAILED);id(key);String text=normalize(q.text(),2000);if(text==null)throw fail(VALIDATION_FAILED);String canonical=json(new CommentInput(q.revision(),text));var existing=jdbc.queryForList("SELECT * FROM merchant.application_review_comment WHERE actor_id=? AND application_id=? AND operation_key=?",actor.accountId(),id,key);if(!existing.isEmpty()){var row=existing.getFirst();byte[] expected=fingerprints.hash(row.get("input_key_id").toString(),"merchantReviewComment",id,1,actor.accountId().toString(),actor.realmId().toString(),canonical,key.toString());try{if(!actor.realmId().equals(row.get("realm_id"))||!MessageDigest.isEqual(expected,(byte[])row.get("input_digest")))throw fail(IDEMPOTENCY_CONFLICT);return commentRow(row);}finally{Arrays.fill(expected,(byte)0);}}
        var row=application(id);if(((Number)row.get("version")).longValue()!=version||((Number)row.get("submitted_revision")).longValue()!=q.revision())throw fail(PRECONDITION_STALE);UUID event=disclosure(actor,app(id),row,Map.of("purpose","MERCHANT_REVIEW_COMMENT","text",text));UUID comment=UUID.randomUUID();byte[] hash=fingerprints.hash(fingerprints.activeKey(),"merchantReviewComment",id,1,actor.accountId().toString(),actor.realmId().toString(),canonical,key.toString());try{jdbc.update("INSERT INTO merchant.application_review_comment(id,application_id,revision,actor_id,realm_id,protected_text,event_id,request_id,created_at,operation_key,input_key_id,input_digest) SELECT ?,?,?,?,?,protected_payload,id,request_id,occurred_at,?,?,? FROM merchant.governance_event WHERE id=?",comment,id,q.revision(),actor.accountId(),actor.realmId(),key,fingerprints.activeKey(),hash,event);}finally{Arrays.fill(hash,(byte)0);}return commentRow(jdbc.queryForMap("SELECT * FROM merchant.application_review_comment WHERE id=?",comment));});}
    @Override public CommentPage comments(AdminCommandContext actor,UUID id,PageQuery q){return scoped(actor,app(id),List.of("application.read","application.evidence.read"),scope->{size(q);var row=application(id);var values=jdbc.queryForList("SELECT * FROM merchant.application_review_comment WHERE application_id=? ORDER BY created_at,id",id);String source=hash("merchantViewSource",scope.version(),row.get("version").toString(),json(values.stream().map(v->List.of(v.get("id"),v.get("event_id"))).toList()));var page=page(actor,values,q,hash("merchantViewQuery","COMMENTS",id.toString()),source);UUID event=disclosure(actor,app(id),row,Map.of("purpose","MERCHANT_REVIEW","kind","COMMENTS"));return new CommentPage(page.items().stream().map(this::commentRow).toList(),page.next(),event);});}
    private List<Check> reviewChecks(AdminCommandContext actor,UUID id,Map<String,Object> row){
        String version=row.get("version").toString();var result=new ArrayList<Check>();boolean contact=true,binding=true;
        try{governance.verifyForViews(actor,id);}catch(GovernanceFailure failure){
            if(!Set.of(CONTACT_PROOF_REQUIRED,EVIDENCE_NOT_READY,STATE_CONFLICT).contains(failure.code()))throw failure;
            binding=false;contact=failure.code()!=CONTACT_PROOF_REQUIRED;
        }
        result.add(new Check("SUBMISSION_BINDING",binding?"PASS":"FAIL",version,null));
        result.add(new Check("CONTACT_REVERIFY_REQUIRED",contact?"PASS":"FAIL",version,null));
        long invalid=jdbc.queryForObject("SELECT count(*) FROM merchant.application_revision_evidence x LEFT JOIN merchant.application_evidence e ON e.id=x.evidence_id AND e.application_id=x.application_id WHERE x.application_id=? AND x.revision=? AND (e.id IS NULL OR e.state<>'CLEAN' OR e.screened_at IS NULL OR e.scan_version IS NULL OR e.sha256<>x.sha256)",Long.class,id,row.get("submitted_revision"));
        result.add(new Check("EVIDENCE_NOT_CLEAN",invalid==0?"PASS":"FAIL",version,null));
        var fields=input(row);long duplicates=jdbc.queryForObject("SELECT count(*) FROM merchant.business_key_registry WHERE jurisdiction_key=? AND entity_type=? AND legal_key=? AND application_id<>?",Long.class,fields.path("jurisdiction").asString(),fields.path("entityType").asString(),legal(fields.path("legalIdentifier").asString()),id);
        result.add(new Check("BUSINESS_KEY_CONFLICT",duplicates==0?"PASS":"FAIL",version,null));
        boolean conflict=actor.accountId().equals(row.get("applicant_account_id"))||Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM merchant.membership m JOIN merchant.membership applicant ON applicant.organization_id=m.organization_id WHERE m.account_id=? AND applicant.account_id=? AND m.state<>'REVOKED' AND applicant.state<>'REVOKED')",Boolean.class,actor.accountId(),row.get("applicant_account_id")));
        result.add(new Check("REVIEWER_CONFLICT",conflict?"FAIL":"PASS",version,null));return result;
    }
    @Override public Checks checks(AdminCommandContext actor,UUID id){return scoped(actor,app(id),List.of("application.read","application.evidence.read"),scope->{var row=application(id);var result=new ArrayList<>(reviewChecks(actor,id,row));result.add(new Check("EXTERNAL_VERIFICATION","UNAVAILABLE",null,null));disclosure(actor,app(id),row,Map.of("purpose","MERCHANT_REVIEW","kind","CHECKS"));return new Checks(id,((Number)row.get("submitted_revision")).longValue(),result,"NOT_EXPOSED","NOT_PROVIDED");});}
}
